// CSD_RATIONALE_BEGIN
// Dead-end–guarded adaptive constrained decoding with heavy '!' penalty.
//
// Root-cause diagnosis from attempts 1–2:
//   1. The constrained parser allows '!' in some grammar states (after '>' etc.),
//      causing a prolonged '!'-repetition loop that exhausts the 900-token budget
//      before '>>' is emitted (9 final_span_unclosed failures).
//   2. SafeRepetitionPenaltyStep(4.0) was insufficient: penalty only accumulates
//      after the first '!' is in `generated`, allowing many '!'s to appear first.
//   3. Spans opened near the end of free generation were unclosed when the budget
//      expired inside the '!' loop; the closeReserve of 80 was too small relative
//      to how quickly the loop consumed budget.
//
// Design:
//   Phase 0 (outside span): UnconstrainedStep until RenderedEndsWith detects "<<".
//   Phase 1a (inside, remaining ≤ closeReserve=200): CloseSpanWithinBudget with
//     all remaining budget; uses dead-end-aware generation internally.
//   Phase 1b (inside, IsCompletePrefix): CloseConstrainedSpan immediately.
//   Phase 1c (inside, DeadEndDetection < 4): narrow grammar state; force-close
//     with CloseSpanWithinBudget(remaining); exits loop.
//   Phase 1d (inside, normal): AdaptiveConstrainedStepWithPenalties with ["!"]
//     penalized by 8.0 logits from the very first token, blocking the '!'-loop
//     before it starts.
//   Final cleanup: if still inside after loop exit, CloseSpanWithinBudget on
//     leftover budget.
//   Prompt guidance: forbid '=' inside << >>, insist on short self-contained
//     expressions, and emphasise int() for whole-number division.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (Phase 1a, remaining <= closeReserve):
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (Phase 0, outside-span):
//     insideConstrainedOut is false before the step; we flip it only when
//     RenderedEndsWith detects "<<", setting currentConstrainedOut := [] which
//     satisfies IsValidPrefix([]) by the method precondition. Otherwise the
//     implication stays vacuously true. ✓
//
//   (Phase 1b, IsCompletePrefix):
//     CloseConstrainedSpan sets insideConstrainedOut := false, making the
//     implication vacuously true. ✓
//
//   (Phase 1c, dead-end):
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (Phase 1d, normal constrained step):
//     AdaptiveConstrainedStepWithPenalties returns either eosToken (break, no
//     state change) or a parser-valid next token (hard-mask postcondition).
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (Phase 1a): CloseSpanWithinBudget(remaining) postcondition: |cg| <= |generated| + remaining.
//     After steps := maxSteps: |cg| <= |generatedPrefix| + steps_before + (maxSteps - steps_before)
//     = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   (Phase 0): steps grows by 1; at most one token appended to generated. ✓
//
//   (Phase 1b): CloseConstrainedSpan appends at most one ">>" token; steps grows by 1. ✓
//
//   (Phase 1c): Same argument as Phase 1a (CloseSpanWithinBudget with remaining,
//     then steps := maxSteps). ✓
//
//   (Phase 1d): steps grows by 1; AppendConstrainedToken appends exactly one
//     visible token when next != eosToken; break (no append) when next == eosToken. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve grade-school math step by step using symbolic variables. " +
  "Wrap each intermediate symbolic expression in << >>. " +
  "The final line MUST be exactly: The final answer is <<expr>>. " +
  "Inside << >>: use only the original variable names from the problem, numbers, " +
  "+, -, *, /, //, %, (), and int(). " +
  "Do NOT write = inside << >>. Keep each << >> expression short and complete. " +
  "Use int() for whole-number (floor) division results. " +
  "Use // for integer division. Never substitute numeric values for symbolic variables.");

var closeReserve: nat := 200;
var deadEndMin: nat := 4;
var penaltyToks: seq<Token> := ["!"];
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low while inside a span: force-close with all remaining budget
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    // Outside a constrained span: free generation
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    // Inside span and already complete: close immediately
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Inside span, not complete, budget ample (remaining > closeReserve >= 200)
    // Detect narrow/dead-end grammar states before spending a token
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, deadEndMin);
    if narrow {
      // Parser narrowed to < deadEndMin choices: escape via force-close
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
      break;
    } else {
      // Normal constrained step: apply heavy '!' penalty to prevent repetition loops
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStepWithPenalties(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, penaltyToks, 8.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

// Final cleanup: close any still-open span with whatever budget remains
if insideConstrainedOut && steps < maxSteps {
  var remaining2: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining2
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

